doServiceAjax('sepoa.svc.admin.AD_410', 'CONNECTION', 'doCheckDuplicateCompany', null, function(so) {
	if(so.status != 1) {
		Alert(Sepoa.cache.text.get('MESSAGE.1002'));
		return;
	}

	var sf = new SepoaFormater(so.result[0]);

	if(sf.getArrayMap().length == 0) {
		createFlag = true;
		Alert(Sepoa.cache.text.get('AD_410_NEW.DO_NOT_OVERLAP'));
	} else {
		createFlag = false;
		Alert(Sepoa.cache.text.get('AD_410_NEW.OVERLAP'));
	}
});


    		if(!formObj.validate()) {
	    		Alert(Sepoa.cache.text.get('MESSAGE.0002'));
