    		if(createFlag == false) {
    			Alert(Sepoa.cache.text.get('AD_410_NEW.DUPLICATE_CHECK_AGAIN'));
    			return;
    		}

    		if(Sepoa.params.callback) {
				Sepoa.params.callback.apply(this, [formObj.getFormData()]);
				selfObj.close();
			}
